import PropTypes from 'prop-types';
import React, { forwardRef, useMemo } from 'react';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useTheme, styled } from '@mui/material/styles';
import CloseIcon from '@mui/icons-material/Close';

import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Grid,
    MenuItem,
    Select,
    Slide,
    TextField,
    FormControl,
    InputLabel,
    FormControlLabel,
    Switch,
    Typography,
    CardMedia,
    Fab,
    Paper
} from '@mui/material';
import Autocomplete from '@mui/material/Autocomplete';
import AnimateButton from 'ui-component/extended/AnimateButton';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';

// ✅ Slide Transition Function
const getSlideDirection = (position) => {
    switch (position) {
        case 'left':
            return 'right';
        case 'right':
            return 'left';
        case 'center':
        default:
            return 'up';
    }
};

const ImageWrapper = styled('div')(({ theme }) => ({
    position: 'relative',
    overflow: 'hidden',
    borderRadius: '4px',
    cursor: 'pointer',
    width: 75,
    height: 75,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: theme.palette.background.default,
    border: `2px solid ${theme.palette.divider}`,
    '& > img': {
        width: '100%',
        height: '100%',
        objectFit: 'cover'
    },
    '& .remove-icon': {
        position: 'absolute',
        top: 5,
        right: 5,
        background: 'rgba(0, 0, 0, 0.6)',
        color: 'white',
        borderRadius: '50%',
        width: 20,
        height: 20,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer'
    }
}));

const Transition = forwardRef(({ position, ...props }, ref) => <Slide direction={getSlideDirection(position)} ref={ref} {...props} />);

// ✅ Dynamic Modal Positioning
const getDialogStyle = (position, theme) => {
    const baseStyle = {
        maxWidth: 450,
        maxHeight: '100%',
        overflowY: 'auto',
        boxShadow: theme.shadows[5]
    };

    if (position === 'right') {
        return { ...baseStyle, position: 'fixed', right: 0, top: 0, bottom: 0, borderRadius: 0 };
    }
    if (position === 'left') {
        return { ...baseStyle, position: 'fixed', left: 0, top: 0, bottom: 0, borderRadius: 0 };
    }
    return { ...baseStyle, margin: 'auto', maxHeight: '90vh', borderRadius: theme.shape.borderRadius };
};

// ✅ Get Initial Value Function
const getInitialValue = (field, editData) => {
    if (editData) {
        if (field.type === 'switch') return Boolean(editData[field.name]);
        if (field.type === 'multiselect') return Array.isArray(editData[field.name]) ? editData[field.name] : [];
        return editData[field.name] || '';
    }

    if (field.defaultValue !== undefined) {
        return field.defaultValue;
    }

    switch (field.type) {
        case 'switch':
            return false;
        case 'multiselect':
            return [];
        default:
            return '';
    }
};

// ✅ Optimize Component Re-Renders
const GenericModelForm = React.memo(
    ({
        open,
        handleCloseDialog,
        position = 'right',
        fields,
        onSubmit,
        formLabel = 'Add',
        editData,
        initialImages,
        setInitialImages,
        removedImages,
        setRemovedImages
    }) => {
        const theme = useTheme();
        const [images, setImages] = React.useState(initialImages || []);
        // ✅ Memoized Form Initial Values (Fixed ESLint Warning)
        const initialValues = useMemo(
            () =>
                fields.reduce((acc, field) => {
                    acc[field.name] = getInitialValue(field, editData);
                    return acc;
                }, {}),
            [fields, editData]
        );

        // http://localhost:3001/
        const BASE_URL = 'https://13.53.197.110:3001'; // ✅ Adjust according to your backend server

        React.useEffect(() => {
            if (editData && editData.images) {
                // ✅ Convert image paths to absolute URLs
                const formattedImages = editData.images.map((img) => ({
                    ...img,
                    image_url: img.image_url.startsWith('http') ? img.image_url : `${BASE_URL}${img.image_url}`
                }));
                setImages(formattedImages);
            } else {
                setImages([]);
            }
        }, [editData]);

        // ✅ Memoized Validation Schema (Fixed ESLint Warning)
        const validationSchema = useMemo(
            () =>
                yup.object(
                    fields.reduce((acc, field) => {
                        if (field.required) {
                            acc[field.name] = yup.mixed().required(`${field.label} is required`);
                        }
                        return acc;
                    }, {})
                ),
            [fields]
        );

        // ✅ Formik Configuration

        const formik = useFormik({
            initialValues,
            validationSchema,
            enableReinitialize: true,
            onSubmit: (values, { resetForm }) => {
                onSubmit({ ...values, images }, resetForm);
                handleCloseDialog();
            }
        });

        const handleDragOver = (event) => {
            event.preventDefault();
            event.dataTransfer.dropEffect = 'copy';
        };

        const handleDrop = (event) => {
            event.preventDefault();
            const files = Array.from(event.dataTransfer.files);
            const newImages = files.map((file) => file); // ✅ Store real File objects

            if (images.length + newImages.length > 5) {
                // eslint-disable-next-line no-alert
                alert('You can upload a maximum of 5 images.');
                return;
            }

            setImages([...images, ...newImages]);
            formik.setFieldValue('images', [...images, ...newImages]); // ✅ Update Formik values
        };

        const handleImageUpload = (event) => {
            const files = Array.from(event.target.files);

            if (images.length + files.length > 5) {
                alert('You can upload a maximum of 5 images.');
                return;
            }

            setImages((prevImages) => [...prevImages, ...files]); // ✅ Keep old images and add new ones
        };

        const handleRemoveImage = (index) => {
            setImages((prevImages) => {
                const removedImage = prevImages[index];
                // ✅ If the removed image is a URL (from database), track it
                if (removedImage && removedImage.image_url) {
                    setRemovedImages((prev) => [...prev, removedImage.image_url]); // ✅ Store URL only
                }
                // ✅ Remove image from `images` state
                return prevImages.filter((_, i) => i !== index);
            });
        };

        const getImageSrc = (image) => {
            if (!image) return ''; // ✅ Prevents errors

            if (image instanceof File) {
                return URL.createObjectURL(image); // ✅ For newly uploaded images
            }

            if (typeof image === 'string') {
                return image.startsWith('http') ? image : `${BASE_URL}${image}`; // ✅ Ensure full URL
            }

            if (image.image_url) {
                return image.image_url.startsWith('http') ? image.image_url : `${BASE_URL}${image.image_url}`;
            }

            return ''; // ✅ Default empty string if no valid image
        };

        // ✅ Use helper function in `CardMedia`
        // ✅ Render Input Field
        const renderField = (field) => {
            // Handle 'status' field dynamically based on `useDropdown`
            if (field.name === 'status' && field.useDropdown === false) {
                return (
                    <FormControlLabel
                        control={
                            <Switch
                                checked={formik.values[field.name]}
                                onChange={(event) => formik.setFieldValue(field.name, event.target.checked)}
                            />
                        }
                        label={field.label}
                    />
                );
            }

            switch (field.type) {
                case 'select':
                    return (
                        <FormControl fullWidth sx={{ mt: 2 }}>
                            <InputLabel
                                shrink
                                sx={{
                                    color: 'primary.main', // Label color
                                    '&.Mui-focused': {
                                        color: 'primary.dark' // Label color when focused
                                    },
                                    '&.Mui-error': {
                                        color: 'error.main' // Label color when error
                                    }
                                }}
                            >
                                {field.label}
                            </InputLabel>
                            <Select
                                fullWidth
                                name={field.name}
                                value={formik.values[field.name]}
                                onChange={formik.handleChange}
                                error={formik.touched[field.name] && Boolean(formik.errors[field.name])}
                                sx={{
                                    '& .MuiSelect-select': {
                                        color: 'text.dark' // Selected value text color
                                    },
                                    '& .MuiOutlinedInput-notchedOutline': {
                                        borderColor: 'grey.300' // Border color
                                    }
                                }}
                                MenuProps={{
                                    PaperProps: {
                                        sx: {
                                            '& .MuiMenuItem-root': {
                                                color: 'text.primary', // Menu item text color
                                                backgroundColor: 'background.paper', // Menu item background
                                                '&:hover': {
                                                    backgroundColor: 'action.hover' // Hover background
                                                },
                                                '&.Mui-selected': {
                                                    backgroundColor: 'primary.light', // Selected item background
                                                    color: 'primary.contrastText' // Selected item text
                                                }
                                            }
                                        }
                                    }
                                }}
                            >
                                {field.options.map((option) => (
                                    <MenuItem
                                        key={option.value}
                                        value={option.value}
                                        sx={{
                                            color: 'text.secondary', // Individual item text color
                                            '&:hover': {
                                                backgroundColor: 'primary.light',
                                                color: 'primary.contrastText'
                                            }
                                        }}
                                    >
                                        {option.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    );

                case 'multiselect':
                    return (
                        <Autocomplete
                            multiple
                            options={field.options}
                            getOptionLabel={(option) => option.name}
                            value={formik.values[field.name] || []}
                            onChange={(event, newValue) => {
                                formik.setFieldValue(field.name, newValue);
                            }}
                            renderInput={(params) => (
                                <TextField
                                    {...params}
                                    label={field.label}
                                    sx={{
                                        mt: 2,
                                        '& .MuiInputLabel-root': {
                                            color: 'primary.dark', // Label color
                                            '&.Mui-focused': {
                                                color: 'primary.dark' // Label color when focused
                                            },
                                            '& .MuiOutlinedInput-root': {
                                                '&:hover .MuiOutlinedInput-notchedOutline': {
                                                    borderColor: 'rgba(0, 0, 0, 0.23)' // Maintain border on hover
                                                },
                                                '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                                                    borderColor: 'rgba(0, 0, 0, 0.23)' // Optional: border color when focused
                                                }
                                            }
                                        }
                                    }}
                                    error={formik.touched[field.name] && Boolean(formik.errors[field.name])}
                                />
                            )}
                            sx={{
                                '& .MuiChip-root': {
                                    // Styles for selected chips
                                    backgroundColor: 'text.primary',
                                    color: 'primary.dark'
                                }
                            }}
                            PaperComponent={({ children }) => (
                                <Paper
                                    sx={{
                                        backgroundColor: 'white',
                                        color: 'primary.dark',
                                        '& .MuiAutocomplete-option': {
                                            '&:hover': {
                                                backgroundColor: 'action.hover'
                                            },
                                            '&[aria-selected="true"]': {
                                                backgroundColor: 'primary.light',
                                                color: 'primary.dark'
                                            }
                                        }
                                    }}
                                >
                                    {children}
                                </Paper>
                            )}
                        />
                    );

                case 'switch':
                    return (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={formik.values[field.name]}
                                    onChange={(event) => formik.setFieldValue(field.name, event.target.checked)}
                                />
                            }
                            label={field.label}
                            sx={{
                                '&& .MuiFormControlLabel-label': {
                                    // Double '&' boosts priority
                                    color: 'primary.dark',
                                    width: '100%'
                                }
                            }}
                        />
                    );

                case 'date':
                    return (
                        <TextField
                            fullWidth
                            name={field.name}
                            label={field.label}
                            type="date"
                            value={formik.values[field.name] ? new Date(formik.values[field.name]).toISOString().split('T')[0] : ''}
                            onChange={formik.handleChange}
                            InputLabelProps={{ shrink: true }}
                            error={formik.touched[field.name] && Boolean(formik.errors[field.name])}
                            helperText={formik.touched[field.name] && formik.errors[field.name]}
                            sx={{ mt: 2 }}
                        />
                    );

                case 'images':
                    return (
                        <Grid item xs={12} sx={{ backgroundColor: theme.palette.text.primary }}>
                            <Typography variant="subtitle1">Upload Images*</Typography>
                            <input
                                type="file"
                                id="file-upload"
                                multiple
                                accept="image/*"
                                style={{ display: 'none' }}
                                onChange={handleImageUpload}
                            />

                            <InputLabel
                                htmlFor="file-upload"
                                onDragOver={handleDragOver}
                                onDrop={handleDrop}
                                sx={{
                                    background: theme.palette.text.primary,
                                    py: 3.75,
                                    px: 0,
                                    textAlign: 'center',
                                    borderRadius: '4px',
                                    border: `1px solid ${theme.palette.text.dark}`,
                                    cursor: 'pointer',
                                    mb: 3,
                                    '& > svg': {
                                        verticalAlign: 'sub',
                                        mr: 0.5
                                    }
                                }}
                            >
                                <CloudUploadIcon /> Drop file here to upload
                            </InputLabel>
                            <Grid container spacing={1}>
                                {images.map((image, index) => (
                                    <Grid item key={index}>
                                        <ImageWrapper>
                                            <CardMedia component="img" image={getImageSrc(image)} title="Uploaded Image" />;
                                            <Fab
                                                color="secondary"
                                                className="remove-icon"
                                                size="small"
                                                onClick={() => handleRemoveImage(index)}
                                            >
                                                <CloseIcon />
                                            </Fab>
                                        </ImageWrapper>
                                    </Grid>
                                ))}
                            </Grid>
                        </Grid>
                    );

                case 'textarea':
                    return (
                        <TextField
                            fullWidth
                            name={field.name}
                            label={field.label}
                            multiline
                            rows={5} // Adjust the number of rows as needed
                            value={formik.values[field.name]}
                            onChange={formik.handleChange}
                            error={formik.touched[field.name] && Boolean(formik.errors[field.name])}
                            helperText={formik.touched[field.name] && formik.errors[field.name]}
                            sx={{
                                mt: 2,
                                '& .MuiOutlinedInput-root': {
                                    '&:hover .MuiOutlinedInput-notchedOutline': {
                                        borderColor: 'rgba(0, 0, 0, 0.23)' // Default border color (or your preferred color)
                                    }
                                }
                            }}
                        />
                    );

                default:
                    return (
                        <TextField
                            fullWidth
                            name={field.name}
                            label={field.label}
                            type={field.type || 'text'}
                            value={formik.values[field.name]}
                            onChange={formik.handleChange}
                            error={formik.touched[field.name] && Boolean(formik.errors[field.name])}
                            helperText={formik.touched[field.name] && formik.errors[field.name]}
                            sx={{
                                mt: 2,
                                '& .MuiInputLabel-root': {
                                    borderColor: 'rgba(0, 0, 0, 0.23)',
                                    color: 'primary.dark', // Custom gray color
                                    '&.Mui-focused': {
                                        color: 'primary.dark' // Blue when focused (matches MUI primary)
                                    },
                                    '&.Mui-error': {
                                        color: 'primary.dark' // Red when there's an error
                                    }
                                },
                                '& .MuiOutlinedInput-root': {
                                    '&:hover .MuiOutlinedInput-notchedOutline': {
                                        borderColor: 'rgba(0, 0, 0, 0.23)'
                                        // Default border color (or your preferred color)
                                    }
                                }
                            }}
                        />
                    );
            }
        };

        return (
            <Dialog
                open={open}
                TransitionComponent={useMemo(() => (props) => <Transition {...props} position={position} />, [position])}
                keepMounted
                onClose={handleCloseDialog}
                maxWidth="sm"
                fullWidth
                sx={{
                    '& .MuiDialog-paper': getDialogStyle(position, theme),
                    '& .MuiPaper-root': {
                        backgroundColor: theme.palette.text.primary // Change dialog background color
                    }
                }}
            >
                <DialogTitle sx={{ color: 'primary.dark', borderBottom: `2px solid ${theme.palette.primary.dark}` }}>
                    {formLabel}
                </DialogTitle>
                <DialogContent>
                    <form onSubmit={formik.handleSubmit}>
                        <Grid container spacing={2}>
                            {fields
                                .filter((field) => field.type !== 'switch')
                                .map((field) => (
                                    <Grid item xs={12} key={field.name}>
                                        {renderField(field)}
                                    </Grid>
                                ))}
                            {(() => {
                                const switchFields = fields.filter((field) => field.type === 'switch');
                                const fullWidthSwitches = switchFields.filter((field) => field.fullWidth);
                                const groupedSwitches = switchFields.filter((field) => !field.fullWidth);

                                return (
                                    <>
                                        {/* Full width switches */}
                                        {fullWidthSwitches.map((field) => (
                                            <Grid item xs={12} key={field.name}>
                                                {renderField(field)}
                                            </Grid>
                                        ))}

                                        {/* Grouped switches - max 3 per row */}
                                        {groupedSwitches.length > 0 && (
                                            <Grid item xs={12}>
                                                <Grid container spacing={2}>
                                                    {groupedSwitches.map((field, index) => (
                                                        <Grid index={index} item xs={12} sm={6} md={6} key={field.name}>
                                                            {renderField(field)}
                                                        </Grid>
                                                    ))}
                                                </Grid>
                                            </Grid>
                                        )}
                                    </>
                                );
                            })()}
                        </Grid>
                        <DialogActions>
                            <AnimateButton>
                                <Button variant="contained" type="submit">
                                    {editData ? 'Update' : 'Submit'}
                                </Button>
                            </AnimateButton>
                            <Button variant="text" color="error" onClick={handleCloseDialog}>
                                Close
                            </Button>
                        </DialogActions>
                    </form>
                </DialogContent>
            </Dialog>
        );
    }
);

// ✅ Prop Types Validation
GenericModelForm.propTypes = {
    open: PropTypes.bool.isRequired,
    handleCloseDialog: PropTypes.func.isRequired,
    position: PropTypes.oneOf(['right', 'center', 'left']),
    fields: PropTypes.array.isRequired,
    onSubmit: PropTypes.func.isRequired,
    editData: PropTypes.object
};

export default GenericModelForm;
